head.script:
scwin.screenId = "jldfil25900";

///////// 1. 변수 및 선언 영역 /////////

scwin.result = "";

scwin.modifiyDate = "";

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (sysYear/listStatCd 확보)
        scwin.init_fillNow(); // 2) sysYear 미수신 시 서버 연도 충전
        scwin.init_attrReals(); // 3) 안내 문구 동적 렌더 (sysYear 확정 후)
        scwin.init_conds(); // 4) 버튼 표시 조건 평가
    } catch (ex) {
        $c.exception.handleError(ex, {
            context: "jldfil25900.onpageload"
        });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description td_16 안내 문구를 sysYear 기준으로 동적 렌더한다(sysYear 확정 후 호출).
 * @returns {void}
 * @hidden N
 * @example scwin.init_attrReals();
 */
scwin.init_attrReals = function() {
    const attrReals = [{
        childId: "td_16",
        attr: "__html",
        fn: function() {
            const sysYear = String($c.data.readValue("dma_pageContext", "sysYear", {
                silent: true
            }));
            if (sysYear.trim() === "") return "";
            return "『배당기준일자 신고』작성하는 화면입니다.<br/> <span style=\"color:red\">" + sysYear +
                "</span>년도 배당기준일 신고는 반드시 <span style=\"color:red\">작성하기</span> 버튼을 눌러서 제출해주시기 바랍니다. (※ " +
                (Number(sysYear) - 1) + "년도 신고내용 수정·제출 금지)";
        }
    }];
    $c.util.applyAttrReals(attrReals);
};

/**
 * @method
 * @name init_fillNow
 * @description dma_pageContext.sysYear 미수신 시 서버 연도로 충전한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_fillNow();
 */
scwin.init_fillNow = function() {
    const pc = $c.util.getComponent("dma_pageContext");
    if (pc && pc.set && !pc.get("sysYear")) {
        pc.set("sysYear", $c.date.getServerDateTime("yyyy"));
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function() {
    $c.data.recvParamData("dma_pageContext");
};

/**
 * @method
 * @name init_conds
 * @description btn_goWrite 표시 조건(listStatCd == "Y")을 평가한다(공용 $c.util.evalConds).
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function() {
    const binds = [{
        id: "btn_goWrite",
        fn: function() {
            return $c.data.readValue("dma_pageContext", "listStatCd", {
                ctx: true,
                label: "listStatCd"
            }) === "Y";
        }
    }];
    $c.util.evalConds(binds);
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_goWrite_onclick
 * @description [작성하기] 버튼 클릭 — 배당기준일자 신고 작성 화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_goWrite_onclick(e);
 */
scwin.btn_goWrite_onclick = async function(e) {
    try {
        await scwin.goWrite();
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25900.btn_goWrite_onclick"
        });
    }
};

/**
 * @method
 * @name grd_dividendDateList_oncellclick
 * @description 목록 행 클릭 — 선택 행의 업무처리번호·기준년도로 상세 화면을 연다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.grd_dividendDateList_oncellclick(0);
 */
scwin.grd_dividendDateList_oncellclick = async function(rowIndex) {
    try {
        const dl = $c.util.getComponent("dlt_dividendDateList");
        const r = (dl && dl.getRowJSON) ? dl.getRowJSON(rowIndex) : null;
        if (r) {
            await scwin.goView(r["bzProcsNo"], r["basYy"]);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, {
            context: "jldfil25900.grd_dividendDateList_oncellclick"
        });
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name tx_fn_modifiyDate
 * @description 배당기준일 수정 가능 여부를 서버에 조회한다. 응답 실패 시 메시지를 알린다.
 * @returns {Object} executeDynamic 응답 객체(resObj)
 * @hidden N
 * @example const res = await scwin.tx_fn_modifiyDate();
 */
scwin.tx_fn_modifiyDate = async function() {
    const sbmOptions = {
        id: "tx_fn_modifiyDate",
        method: "post",
        action: "dividendBaseDate.do",
        ref: "dma_modifiyDateReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) {
            await $c.win.alert(res.responseJSON.message);
        }
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name goWrite
 * @description 배당기준일자 신고 작성 화면(jldfil25910)으로 이동한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.goWrite();
 */
scwin.goWrite = async function() {
    $("input[name='method']").val("dividendDateModifiy");
    $("input[name='status']").val("R");
    $("form[name='dividendDateForm']").attr("action", "dividendBaseDate.do");
    $c.win.moveUrl("/jldfil25910/jldfil25910.xml", {
        "method": "dividendDateModifiy",
        "status": "R"
    });
};

/**
 * @method
 * @name goView
 * @description 선택 종목의 배당기준일자 상세 화면(jldfil25910)으로 이동한다.
 * @param {String} ipt_bzProcsNo 업무처리번호
 * @param {String} basYear 기준년도
 * @returns {void}
 * @hidden N
 * @example await scwin.goView(bzProcsNo, basYy);
 */
scwin.goView = async function(ipt_bzProcsNo, basYear) {
    $("input[name='method']").val("dividendDateModifiy");
    $("input[name='status']").val(await scwin.fn_modifiyDate());
    $("input[name='bzProcsNo']").val(ipt_bzProcsNo);
    $("form[name='dividendDateForm']").attr("action", "dividendBaseDate.do");
    $c.win.moveUrl("/jldfil25910/jldfil25910.xml", {
        "method": "dividendDateModifiy",
        "bzProcsNo": ipt_bzProcsNo
    });
};

/**
 * @method
 * @name fn_modifiyDate
 * @description 수정 가능 여부 조회(tx_fn_modifiyDate) 후 결과를 scwin.result/modifiyDate 에 반영한다.
 * @returns {Object} executeDynamic 응답 객체(resObj)
 * @hidden N
 * @example const res = await scwin.fn_modifiyDate();
 */
scwin.fn_modifiyDate = async function() {
    const res = await scwin.tx_fn_modifiyDate();
    const body = (res && res.responseJSON && (res.responseJSON.body != null ? res.responseJSON.body : res.responseJSON)) || {};
    scwin.result = body;
    scwin.modifiyDate = scwin.result.checkModifiyDate;
    return res;
};
